from pathlib import Path
import json
BASE=Path('episodes/inventions-since-2000');PUB=Path('public/episodes/inventions-since-2000')
records=[]
for p in sorted((PUB/'archive').glob('*.json')):
 x=json.loads(p.read_text());records.append(x)
(BASE/'archive-assets.json').write_text(json.dumps(records,indent=2,ensure_ascii=False)+'\n')
lines=['# Image credits','','Reference photographs and illustrations downloaded from Wikimedia Commons. Colours are retained; framing, scaling or cropping may be applied. Source files remain under the licenses below. Generated artwork and original animation are separate.','']
for x in records:lines.append(f'- **{x["id"]}**: {x["title"]}. {x["artist"]}. [{x["license"]}]({x["licenseUrl"] or x["sourcePage"]}). [Source]({x["sourcePage"]}). Editorial crop and framing.')
lines+=['','## Production and libraries','','- OpenAI Image API, gpt-image-2: 11 landscape environment plates, five 4-pose Miko sheets and a 4-item science sheet. Prompts and raw outputs: `output/imagegen/inventions-v1/`. Character sheets reference the existing Miko microwave sheet.','- OpenAI native GIF model gpt-image-2.6-sunburst: wake, book weight and phone swipe. Original GIFs, requests, native provenance and transparent render atlases are retained in their versioned `output/imagegen/miko-inventions-*-v1/` folders. No locally synthesised motion is described as native generation.','- ElevenLabs Amara, eleven_v4: chosen chapter recordings documented in `voice-selections.json`. The original cold-open recording is reused. The user selected the shorter supplied script; expanded narration experiments are not used in the film.','- ElevenLabs Music v2: three original instrumental cues, curiosity, city and future. Five locally saved ElevenLabs Sound Effects v2 assets plus deterministic cut ticks and tonal accents. IDs are in `sound-provenance.json`.','- Blender 5.2.3 LTS: four original packed hero scenes, source in `blender/scripts/inventions_heroes_v1.py`.','- HyperFrames count-up and chat-message primitives are installed as editable source; modified instances use local fonts and GSAP.','- DM Sans and Inter Variable fonts, with their SIL Open Font Licenses, are saved under the HyperFrames assets/fonts folder.','- Lucide generic SVG icons: ISC license. Canonical product marks from SVG Logos and Simple Icons: CC0 collections, with underlying brand rights retained by their owners. Source commit URLs and licenses are saved in public/episodes/inventions-since-2000/visual-library-provenance-v2.json.','- In v2, the original character sheets and native GIF frames have corrected chroma mattes. Their original poses, pivot coordinates and timing are retained. The four Blender sources are rendered at native 1920×1080, 48 Eevee samples.','','All user interfaces in the animation are schematic recreations. The archive reference image of the original iPhone is a Commons illustration, not a photograph. Generated images of DNA and proteins are explanatory illustrations, not structural measurements.']
(BASE/'CREDITS.md').write_text('\n'.join(lines)+'\n')
t=json.loads((BASE/'timeline.json').read_text());rows=['Every Invention Since 2000 That Changed Your Life','','Eight milestones that changed everyday life: Wikipedia, Uber, Google Maps, YouTube, TikTok, CRISPR, the iPhone and ChatGPT. Miko explores the mechanisms and the habits they made possible.','','CHAPTERS']
for c in t['chapters']:
 sec=int(c['start']);rows.append(f'{sec//60}:{sec%60:02d} '+(str(c['rank'])+'. ' if c.get('rank') else '')+c['title'])
rows+=['','Which invention would you add, and what will be number one in 2050?','','SOURCES','Research and factual qualifications are saved in FACTS.md. Key primary sources:','https://wikimediafoundation.org/wikipedia20/','https://www.uber.com/us/en/newsroom/ubers-founding/','https://blog.google/products-and-platforms/products/maps/look-back-15-years-mapping-world/','https://blog.youtube/inside-youtube/new-era-video-infrastructure/','https://newsroom.tiktok.com/how-tiktok-recommends-videos-for-you?lang=en','https://www.nobelprize.org/prizes/chemistry/2020/summary/','https://www.gov.uk/government/news/mhra-authorises-world-first-gene-therapy-that-aims-to-cure-sickle-cell-disease-and-transfusion-dependent-thalassemia','https://www.apple.com/newsroom/2007/01/09Apple-Reinvents-the-Phone-with-iPhone/','https://openai.com/index/chatgpt/','https://arxiv.org/abs/1706.03762','','IMAGE CREDITS']
for x in records:rows.append(f'{x["title"]} — {x["artist"]} — {x["license"]}: {x["sourcePage"]}. Cropped/resized; source license applies to the image.')
rows+=['','Made with original pixel artwork, Blender animation, HyperFrames and ElevenLabs narration/music. Interfaces and molecular scenes are explanatory recreations.','#inventions #technology #science #history #norbertexplains']
(BASE/'youtube-description.txt').write_text('\n'.join(rows).replace(' — ',' | ')+'\n')
print('Saved credits and upload description with chapters.')
